const COOLDOWN_MS = 7 * 24 * 60 * 60 * 1000; // 7 dias por repositório
const STATE_RETENTION_MS = 90 * 24 * 60 * 60 * 1000; // poda entradas antigas (> 90 dias)

const staticData = $getWorkflowStaticData("global");
if (!staticData.repoState || typeof staticData.repoState !== "object") {
  staticData.repoState = {};
}

const nowMs = Date.now();
const nowIso = new Date(nowMs).toISOString();

// Poda entradas muito antigas para evitar crescimento ilimitado do staticData
for (const [key, entry] of Object.entries(staticData.repoState)) {
  const evaluatedMs = Date.parse(entry?.evaluatedAt || "");
  if (Number.isFinite(evaluatedMs) && nowMs - evaluatedMs > STATE_RETENTION_MS) {
    delete staticData.repoState[key];
  }
}

// O nó anterior devolve o envelope da API do GitHub ({items: [...]}) como um único item n8n
const rawRepos = $input.all().flatMap(i => Array.isArray(i.json?.items) ? i.json.items : []);

const seenInBatch = new Set();
let skippedCooldown = 0;
let skippedUnchanged = 0;
const atualizados = [];

for (const r of rawRepos) {
  if (!r || !r.full_name) continue;
  const key = String(r.full_name).toLowerCase();
  if (seenInBatch.has(key)) continue;
  seenInBatch.add(key);

  // Compatibilidade com chaves legadas (case-sensitive) gravadas antes da normalização
  const anterior = staticData.repoState[key] || staticData.repoState[r.full_name];
  if (anterior) {
    const evaluatedMs = Date.parse(anterior.evaluatedAt || "");
    if (Number.isFinite(evaluatedMs) && nowMs - evaluatedMs < COOLDOWN_MS) {
      skippedCooldown += 1;
      continue;
    }
    if (anterior.lastPushedAt && anterior.lastPushedAt === r.pushed_at) {
      skippedUnchanged += 1;
      continue;
    }
  }

  atualizados.push({ repo: r, key });
}

console.log("[radar-filtro]", JSON.stringify({
  scanned: rawRepos.length,
  passed: atualizados.length,
  skippedCooldown,
  skippedUnchanged
}));

if (atualizados.length === 0) {
  return [];
}

// Registra avaliação com chave normalizada (remove chave legada com maiúsculas se existir)
for (const { repo: r, key } of atualizados) {
  if (r.full_name !== key && staticData.repoState[r.full_name]) {
    delete staticData.repoState[r.full_name];
  }
  staticData.repoState[key] = {
    lastPushedAt: r.pushed_at,
    evaluatedAt: nowIso
  };
}

// Limpa chaves legadas
delete staticData.lastRepoFullNames;
delete staticData.analyzedRepos;

return atualizados.map(({ repo: r }) => ({
  json: {
    owner: r.owner?.login || "",
    repo: r.name || "",
    full_name: r.full_name,
    html_url: r.html_url,
    description: r.description || "Sem descrição",
    pushed_at: r.pushed_at,
    stars: r.stargazers_count || 0,
    language: r.language || "N/A"
  }
}));

const repos = $('Code — Filtro + Cooldown').all();
const readmes = $('HTTP — README').all();
const commitsList = $('HTTP — Últimos Commits').all();

return repos.map((repoItem, i) => {
  const repo = repoItem.json;

  // Extrai o README (texto bruto ou fallback se deu 404)
  const readmeEntry = readmes[i]?.json;
  const readmeRaw = readmeEntry?.error
    ? 'README não encontrado.'
    : (readmeEntry?.data ?? readmeEntry ?? '');
  const readmeText = typeof readmeRaw === 'string'
    ? readmeRaw
    : JSON.stringify(readmeRaw);

  // Com fullResponse: true, o array de commits fica em json.body (garante alinhamento 1:1)
  const commitsBody = commitsList[i]?.json?.body;
  const commits = Array.isArray(commitsBody) ? commitsBody : [];

  const resumoCommits = commits
    .map((c) => {
      const msg = c.commit?.message?.split('\n')[0] || '';
      const autor = c.commit?.author?.name || c.author?.login || 'desconhecido';
      const data = c.commit?.author?.date || '';
      return `- ${data} | ${autor}: ${msg}`;
    })
    .join('\n');

  return {
    json: {
      ...repo,
      readme_cortado: readmeText.slice(0, 5000),
      commits_resumo: resumoCommits || 'Sem commits recentes legíveis'
    }
  };
});

