parameters.jsCode:
return items.map(item => {
  let output = null;
  const raw = item.json?.error?.output || item.json?.error?.context?.raw || item.json?.text || '';
  try {
    const jsonMatch = raw.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try {
        output = JSON.parse(jsonMatch[0]);
      } catch (e) {
        const notaMatch = jsonMatch[0].match(/"nota"\s*:\s*(\d+)/);
        const resumoMatch = jsonMatch[0].match(/"resumo_discord"\s*:\s*"([\s\S]*?)"(?=\s*,\s*"[^"]+"\s*:)/);
        const ideiaMatch = jsonMatch[0].match(/"ideia_no_code"\s*:\s*"([\s\S]*?)"(?=\s*,\s*"[^"]+"\s*:)/);
        const tituloMatch = jsonMatch[0].match(/"titulo_discussao"\s*:\s*"([\s\S]*?)"(?=\s*,\s*"[^"]+"\s*:)/);
        const corpoMatch = jsonMatch[0].match(/"corpo_discussao"\s*:\s*"([\s\S]*?)"\s*\}/);
        if (notaMatch) {
          output = {
            relevante: parseInt(notaMatch[1]) >= 6,
            nota: parseInt(notaMatch[1]),
            camada: 'Outro',
            estagio: 'Companion agora',
            resumo_discord: resumoMatch ? resumoMatch[1].replace(/\\"/g, '"') : 'Resumo recuperado da IA',
            ideia_no_code: ideiaMatch ? ideiaMatch[1].replace(/\\"/g, '"') : '',
            titulo_discussao: tituloMatch ? tituloMatch[1] : 'Ideia do repositório',
            corpo_discussao: corpoMatch ? corpoMatch[1].replace(/\\n/g, '\n') : ''
          };
        }
      }
    }
  } catch (err) {}

  if (!output) {
    output = {
      nota: 0,
      relevante: false,
      camada: 'Outro',
      estagio: 'Companion agora',
      resumo_discord: 'Falha na avaliação automática da IA.',
      ideia_no_code: 'Não foi possível gerar ideia no-code.',
      titulo_discussao: 'Falha na avaliação automática',
      corpo_discussao: 'Não foi possível avaliar este repositório automaticamente.'
    };
  }

  return {
    json: {
      ...item.json,
      output
    }
  };
});

